export default {
  async fetch(request, env) {
    const timeoutMs = Number(env.ORIGIN_TIMEOUT_MS || 5000);
    try {
      const incoming = new URL(request.url);
      const origin = new URL(env.ORIGIN_URL);
      origin.pathname = incoming.pathname;
      origin.search = incoming.search;

      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);

      const originResponse = await fetch(origin.toString(), {
        method: request.method,
        headers: request.headers,
        body: ['GET', 'HEAD'].includes(request.method) ? undefined : request.body,
        redirect: 'manual',
        signal: controller.signal,
      });
      clearTimeout(timer);
      return originResponse;
    } catch (err) {
      return maintenancePage(env);
    }
  },
};

// Banner Joybot (base64 webp), biar gak perlu hosting file gambar terpisah.
const BANNER_B64 = "";

const WA_SVG = '<svg viewBox="0 0 32 32" width="18" height="18" fill="currentColor"><path d="M16.001 3C9.107 3 3.5 8.606 3.5 15.5c0 2.42.678 4.68 1.855 6.605L3 29l7.1-2.32A12.44 12.44 0 0 0 16 28.5c6.894 0 12.5-5.606 12.5-12.5S22.895 3 16.001 3zm7.373 17.847c-.311.876-1.548 1.604-2.532 1.813-.674.143-1.554.256-4.518-.97-3.79-1.568-6.23-5.409-6.42-5.66-.183-.251-1.53-2.037-1.53-3.887s.965-2.76 1.31-3.138c.29-.317.674-.398.9-.398.226 0 .452.002.65.012.208.01.489-.079.766.583.29.69.984 2.383 1.07 2.557.087.174.146.378.03.61-.116.234-.174.378-.348.583-.174.203-.365.454-.522.61-.174.174-.356.363-.153.71.203.348.905 1.494 1.943 2.42 1.335 1.19 2.462 1.559 2.81 1.734.348.174.552.146.756-.087.203-.234.87-1.014 1.102-1.363.232-.348.464-.29.783-.174.319.116 2.025.955 2.373 1.13.348.174.58.26.667.406.087.146.087.844-.224 1.72z"/></svg>';
const TG_SVG = '<svg viewBox="0 0 240 240" width="18" height="18" fill="currentColor"><path d="M120 0C53.7 0 0 53.7 0 120s53.7 120 120 120 120-53.7 120-120S186.3 0 120 0zm55.6 82.1-19.6 92.5c-1.5 6.6-5.4 8.2-10.9 5.1l-30.1-22.2-14.5 14c-1.6 1.6-2.9 2.9-6 2.9l2.1-30.4 55.4-50.1c2.4-2.2-.5-3.4-3.7-1.2l-68.5 43.1-29.5-9.2c-6.4-2-6.5-6.4 1.3-9.5l115.2-44.4c5.3-2 9.9 1.3 8.2 9.4z"/></svg>';

function maintenancePage(env) {
  const siteName = env.SITE_NAME || 'Joybot';

  const ownerWa = env.OWNER_WA_URL || '';
  const ownerTg = env.OWNER_TG_URL || '';
  const channelWa = env.CHANNEL_WA_URL || '';
  const channelTg = env.CHANNEL_TG_URL || '';
  const groupWa = env.GROUP_WA_URL || '';
  const groupTg = env.GROUP_TG_URL || '';

  const icons = { wa: WA_SVG, tg: TG_SVG };

  const link = (url, kind, label, sub) => url
    ? `<a class="dl ${kind}" href="${esc(url)}" target="_blank" rel="noopener">
         <span class="dl-ic">${icons[kind]}</span>
         <span class="dl-txt"><span class="dl-sub">${esc(sub)}</span><span class="dl-label">${esc(label)}</span></span>
       </a>`
    : '';

  const ownerBlock = (ownerWa || ownerTg) ? `
      <div class="section-title">Hubungi Owner</div>
      <div class="grid">
        ${link(ownerWa, 'wa', 'WhatsApp', 'Owner')}
        ${link(ownerTg, 'tg', 'Telegram', 'Owner')}
      </div>` : '';

  const channelBlock = (channelWa || channelTg) ? `
      <div class="section-title">Channel Resmi</div>
      <div class="grid">
        ${link(channelWa, 'wa', 'WhatsApp', 'Channel')}
        ${link(channelTg, 'tg', 'Telegram', 'Channel')}
      </div>` : '';

  const groupBlock = (groupWa || groupTg) ? `
      <div class="section-title">Grup Komunitas</div>
      <div class="grid">
        ${link(groupWa, 'wa', 'WhatsApp', 'Grup')}
        ${link(groupTg, 'tg', 'Telegram', 'Grup')}
      </div>` : '';

  const html = `<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
<title>${esc(siteName)} — Sedang Maintenance</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap');
:root{
  --cream:#FFF7E4; --ink:#000000; --mint:#8CE64C; --yellow:#FFCB3D; --blue:#4CC3F5;
  --card:#FFFFFF; --muted:#54524A;
  --display:'Baloo 2', sans-serif; --body:'Plus Jakarta Sans', sans-serif;
  --bw:2.5px; --shadow-soft:4px 4px 0 var(--ink); --shadow-lift:7px 7px 0 var(--ink);
  --radius-lg:22px; --radius-md:16px;
}
*{box-sizing:border-box;}
html{background:var(--cream);}
body{
  margin:0; min-height:100vh; display:flex; align-items:center; justify-content:center;
  font-family:var(--body); color:var(--ink); background:var(--cream); padding:28px 18px;
  background-image:radial-gradient(rgba(11,11,12,0.08) 1.2px, transparent 1.2px);
  background-size:22px 22px;
}
a{text-decoration:none; color:inherit;}
.wrap{max-width:460px; width:100%;}
.card{
  background:var(--card); border:var(--bw) solid var(--ink); border-radius:var(--radius-lg);
  box-shadow:var(--shadow-lift); overflow:hidden; text-align:center;
}
.banner{width:100%; aspect-ratio:16/9; object-fit:cover; display:block; border-bottom:var(--bw) solid var(--ink);}
.card-body{padding:26px 26px 30px;}
.badge{
  display:inline-flex; align-items:center; gap:7px; font-family:var(--body); font-weight:700;
  font-size:12.5px; background:var(--yellow); color:var(--ink); border:1.5px solid var(--ink);
  padding:6px 14px; border-radius:999px; margin-bottom:16px;
}
.dot{width:7px; height:7px; border-radius:50%; background:var(--ink); animation:pulse 1.3s infinite;}
@keyframes pulse{0%,100%{opacity:1;}50%{opacity:.25;}}
h1{font-family:var(--display); font-size:22px; margin:0 0 8px; font-weight:800;}
p.desc{font-size:14.5px; line-height:1.6; color:var(--muted); margin:0 0 6px;}
.section-title{
  font-family:var(--display); font-weight:700; font-size:13px; color:var(--muted);
  text-transform:uppercase; letter-spacing:.04em; text-align:left; margin:20px 0 10px;
}
.grid{display:grid; grid-template-columns:1fr 1fr; gap:10px;}
.dl{
  display:flex; align-items:center; gap:9px; padding:11px 12px; border-radius:var(--radius-md);
  border:var(--bw) solid var(--ink); background:var(--card); box-shadow:var(--shadow-soft);
  text-align:left;
}
.dl-ic{
  width:32px; height:32px; flex:none; border-radius:9px; display:flex; align-items:center;
  justify-content:center; border:1.5px solid var(--ink); background:var(--card); color:var(--ink);
}
.dl-txt{display:flex; flex-direction:column; gap:1px; min-width:0;}
.dl-sub{font-size:10px; color:var(--muted); font-weight:600;}
.dl-label{font-family:var(--display); font-size:13.5px; font-weight:700;}
.dl.wa{background:var(--mint);}
.dl.wa .dl-ic{background:#fff; color:#25D366;}
.dl.tg{background:var(--blue);}
.dl.tg .dl-ic{background:#fff; color:#229ED9;}
.foot{margin-top:22px; font-size:11.5px; color:var(--muted);}
</style>
</head>
<body>
  <div class="wrap">
    <div class="card">
      <img class="banner" src="data:image/webp;base64,${BANNER_B64}" alt="${esc(siteName)}">
      <div class="card-body">
        <div class="badge"><span class="dot"></span> Sedang Maintenance</div>
        <h1>${esc(siteName)} lagi istirahat sebentar</h1>
        <p class="desc">Server sedang dalam perbaikan/pemeliharaan. Halaman ini otomatis normal lagi begitu server nyala — gak perlu refresh manual. Sambil nunggu, pantau info update lewat channel resmi ya.</p>
        ${ownerBlock}
        ${channelBlock}
        ${groupBlock}
        <div class="foot">© ${new Date().getFullYear()} ${esc(siteName)}</div>
      </div>
    </div>
  </div>
</body>
</html>`;

  return new Response(html, {
    status: 503,
    headers: { 'content-type': 'text/html; charset=UTF-8', 'cache-control': 'no-store', 'retry-after': '30' },
  });
}

function esc(s) {
  return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
}
